<?php
$periodId=isset($_GET['id_tahun_ajaran'])?input_id($_GET,'id_tahun_ajaran'):(int)active_period()['id_tahun_ajaran'];
$date=isset($_GET['tanggal'])?input_date($_GET,'tanggal'):date('Y-m-d');ak_period($periodId,false,$date);
$scope='j.id_tahun_ajaran=? AND w.terverifikasi=1 AND w.mulai<=? AND w.selesai>=?';$args=[$periodId,$date,$date];$role=current_user()['role'];
if($role==='guru'){$scope.=' AND j.id_guru=?';$args[]=user_reference();}
elseif($role==='siswa'){$scope.=' AND EXISTS(SELECT 1 FROM ak_anggota_kelas a WHERE a.nis=? AND a.id_kelas=j.id_kelas AND a.id_tahun_ajaran=j.id_tahun_ajaran AND a.mulai<=? AND a.selesai>=?)';array_push($args,(string)user_reference(),$date,$date);}
$rows=ak_rows("SELECT j.*,k.nama_kelas,m.nama_mapel,g.nama_guru,w.mulai,w.selesai FROM jadwal j JOIN ak_penugasan w ON w.id_jadwal=j.id_jadwal JOIN kelas k ON k.id_kelas=j.id_kelas JOIN mata_pelajaran m ON m.id_mapel=j.id_mapel JOIN guru g ON g.id_guru=j.id_guru WHERE $scope ORDER BY FIELD(j.hari,'Senin','Selasa','Rabu','Kamis','Jumat'),j.jam_mulai",$args);
?><form method="get" class="panel form-grid filter"><?php ak_hidden('view','jadwal');ak_hidden('id_tahun_ajaran',$periodId);ak_field('tanggal','Jadwal mingguan yang berlaku pada tanggal',$date,'date');?><button class="secondary">Tampilkan</button></form><section class="panel"><h2>Jadwal terverifikasi</h2><p>Jadwal memakai keanggotaan kelas dan rentang penugasan yang berlaku. Penugasan legacy tanpa periode/rentang tidak memberikan akses pengisian baru.</p><?php if(!$rows):?><p>Tidak ada jadwal dalam cakupan pengguna pada tanggal ini.</p><?php endif;foreach($rows as $row):?><article class="history-entry"><strong><?=e($row['hari'])?> · <?=e(substr($row['jam_mulai'],0,5))?>–<?=e(substr($row['jam_selesai'],0,5))?></strong><p><?=e($row['nama_kelas'])?> · <?=e($row['nama_mapel'])?><br><?=e($row['nama_guru'])?> · Ruang <?=e($row['ruang']??'—')?> · <?=e($row['status'])?></p><?php if($role==='guru'&&$row['status']==='aktif'):?><a class="button secondary" href="<?=e(ak_link('pertemuan',['id_jadwal'=>$row['id_jadwal']]))?>">Buka pertemuan</a><?php endif;?></article><?php endforeach;?></section>
